import { Field, Input } from '@xala/ds';

export function Example() {
  return (
    <Field>
      <Field.Label>Email address</Field.Label>
      <Field.Input
        type="email"
        placeholder="name@example.com"
        required
      />
      <Field.Description>
        We'll never share your email with anyone else.
      </Field.Description>
      <Field.Error>This field is required</Field.Error>
    </Field>
  );
}

themeSwitcherExample.code:
import { DesignsystemetProvider, Select, Label } from '@xala/ds';
import { THEMES } from '@xala/ds-themes';

export function ThemeSwitcher() {
  const [theme, setTheme] = useState('digdir');

  return (
    <DesignsystemetProvider theme={theme}>
      <div style={{ padding: 24 }}>
        <div style={{ marginBottom: 16 }}>
          <Label htmlFor="theme-select">Select Theme</Label>
          <Select
            id="theme-select"
            value={theme}
            onChange={(e) => setTheme(e.target.value)}
          >
            {Object.keys(THEMES).map(key => (
              <option key={key} value={key}>{key}</option>
            ))}
          </Select>
        </div>
      </div>
    </DesignsystemetProvider>
  );
}
